<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {Trash2,Download,RefreshCw} from 'lucide-vue-next'
import Sheet from '../components/Sheet.vue'
import {useLocal} from '../stores/local'
import {exportLocalBackup} from '../repositories/local-backup'
import type {BranchDeletionPlan,DeletionReceipt} from '../repositories/local-deletion'
const props=defineProps<{branchId:string}>(),emit=defineEmits<{close:[];deleted:[DeletionReceipt]}>(),store=useLocal()
const plan=ref<BranchDeletionPlan|null>(null),error=ref(''),loading=ref(true),busy=ref(false),confirmed=ref(false),password=ref(''),backupSaved=ref(false),receipt=ref<DeletionReceipt|null>(null)
const control=new AbortController();let disposed=false,operationId=crypto.randomUUID()
async function load(){const vault=store.vault;if(!vault)return;loading.value=true;confirmed.value=false;error.value='';try{const previous=await vault.lastBranchDeletion(props.branchId);if(previous){receipt.value=previous;return}const result=await vault.previewBranchDeletion(props.branchId,control.signal);if(!disposed&&store.vault===vault){plan.value=result;operationId=crypto.randomUUID()}}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)loading.value=false}}
async function backup(){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';try{const bytes=await exportLocalBackup(vault,password.value,false,control.signal);if(disposed||store.vault!==vault||!vault.unlocked)return;const url=URL.createObjectURL(new Blob([Uint8Array.from(bytes)],{type:'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download='故事线删除前备份.storyvault';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);backupSaved.value=true;password.value=''}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
async function remove(){const vault=store.vault,current=plan.value;if(!vault||!current||busy.value||!confirmed.value||current.blockers.length||current.activeTasks.length)return;busy.value=true;error.value='';try{const result=await vault.deleteBranch(operationId,props.branchId,current.fingerprint,control.signal);if(!disposed&&store.vault===vault){receipt.value=result;emit('deleted',result)}}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
function locked(){control.abort();emit('close')}
onMounted(()=>{void load();window.addEventListener('reader-local-locked',locked)})
onUnmounted(()=>{disposed=true;control.abort();password.value='';window.removeEventListener('reader-local-locked',locked)})
</script>
<template><Sheet title="删除故事线" return-focus="[aria-label='全览故事线']" @close="!busy&&emit('close')"><div class="branch-delete-panel"><p v-if="loading" role="status">正在检查关联…</p><p v-if="error" class="final-error" role="alert">{{error}}</p><div v-if="receipt" class="deletion-result" role="status"><Trash2 :size="24"/><h3>故事线已删除</h3><p>{{receipt.documentIds.length}} 项记录已清理，原文保留。</p><button class="final-primary" @click="emit('close')">完成</button></div><template v-else-if="plan"><header><h3>{{plan.name}}</h3><small>{{plan.items.length}} 项记录 · {{plan.historyVersions}} 个历史版本</small></header><ul class="deletion-items" aria-label="将删除的记录"><li v-for="item in plan.items.slice(0,80)" :key="item.id"><span>{{item.label}}</span><small>{{item.versions}} 个版本</small></li><li v-if="plan.items.length>80">另有 {{plan.items.length-80}} 项</li></ul><section v-if="plan.blockers.length||plan.activeTasks.length" class="deletion-blockers"><h4>先处理关联</h4><p v-if="plan.blockers.length">{{plan.blockers.length}} 个后代或独立对象仍在使用这条线。</p><p v-if="plan.activeTasks.length">{{plan.activeTasks.length}} 个任务未结束或响应待确认。</p><ul><li v-for="item in [...plan.blockers,...plan.activeTasks].slice(0,80)" :key="item.id"><RouterLink v-if="item.kind==='branch'" :to="{path:'/local/read/'+plan.storyId,query:{branch:item.id}}">{{item.label}}</RouterLink><span v-else>{{item.label}}</span></li></ul></section><details><summary><Download :size="16"/>{{backupSaved?'备份文件已导出':'先导出加密备份'}}</summary><form @submit.prevent="backup"><label>备份口令<input v-model="password" type="password" autocomplete="new-password" minlength="8" maxlength="1024" :disabled="busy" required></label><button :disabled="busy||password.length<8">导出私人库备份</button></form></details><label v-if="!plan.blockers.length&&!plan.activeTasks.length" class="deletion-confirm"><input v-model="confirmed" type="checkbox" :disabled="busy">删除正文、候选和关联记录；可从删除前的备份恢复。</label><footer><button :disabled="busy" @click="load"><RefreshCw :size="16"/>重新检查</button><button class="deletion-button" :disabled="busy||!confirmed||!!plan.blockers.length||!!plan.activeTasks.length" @click="remove"><Trash2 :size="17"/>{{busy?'正在处理…':'删除故事线'}}</button></footer></template></div></Sheet></template>
<style scoped>
.branch-delete-panel{display:grid;gap:24px}.branch-delete-panel h3{margin:0 0 8px;font:26px serif}.branch-delete-panel small{color:var(--muted)}.deletion-items{margin:0;padding:0;list-style:none;max-height:240px;overflow:auto}.deletion-items li{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid var(--edge)}.deletion-items span{min-width:0;overflow-wrap:anywhere}.deletion-items small{white-space:nowrap}.deletion-blockers{padding:20px;background:var(--wash);border-radius:16px}.deletion-blockers h4{margin:0 0 12px}.deletion-blockers ul{padding-left:20px;max-height:200px;overflow:auto}.branch-delete-panel details{border:1px solid var(--edge);padding:16px;border-radius:16px}.branch-delete-panel summary{display:flex;align-items:center;gap:8px;cursor:pointer;min-height:44px}.branch-delete-panel form{display:grid;gap:16px;margin-top:16px}.branch-delete-panel input:not([type=checkbox]){width:100%;min-height:44px}.deletion-confirm{display:flex;align-items:start;gap:12px;line-height:1.8}.deletion-confirm input{width:20px;height:20px;flex:0 0 auto;margin-top:5px}.branch-delete-panel footer{display:flex;justify-content:space-between;gap:12px}.branch-delete-panel button{display:inline-flex;justify-content:center;align-items:center;gap:8px;min-height:44px}.deletion-button{background:#ad3e38;color:white;border-color:#ad3e38}.deletion-button:disabled{opacity:.45}.deletion-result{display:grid;justify-items:start;gap:16px;padding:16px 0}
</style>
